#!/usr/bin/env node
"use strict";
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const E=require('../../public/engine.js');
const P=require('./lib/sfcdft3-production.js');
const I=require('./lib/sfcdft3-independent.js');
const ROOT=path.resolve(process.cwd());
const SPEC=JSON.parse(fs.readFileSync(path.join(ROOT,'doc/structural-forcing-corridor-tree-raw-transfer/prereg/STUDY_3_STAGE_1_COMPATIBILITY_SPEC.json'),'utf8'));
function need(x,m){if(!x)throw new Error(m);}function parse(){const a=process.argv.slice(2),o={};for(let i=0;i<a.length;i++)if(a[i].startsWith('--'))o[a[i].slice(2)]=a[i+1]&&!a[i+1].startsWith('--')?a[++i]:true;return o;}function sha(buf){return crypto.createHash('sha256').update(buf).digest('hex');}function stable(x){if(x===null||typeof x!=='object')return JSON.stringify(x);if(Array.isArray(x))return`[${x.map(stable).join(',')}]`;return`{${Object.keys(x).sort().map(k=>`${JSON.stringify(k)}:${stable(x[k])}`).join(',')}}`;}function blob(file){const b=fs.readFileSync(file),h=Buffer.from(`blob ${b.length}\0`);return crypto.createHash('sha1').update(h).update(b).digest('hex');}function readBound(rel,expected){const f=path.join(ROOT,rel);need(fs.existsSync(f),`bound file missing ${rel}`);need(blob(f)===expected,`bound blob mismatch ${rel}`);return JSON.parse(fs.readFileSync(f,'utf8'));}function walk(dir){let out=[];for(const e of fs.readdirSync(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())out=out.concat(walk(p));else if(e.isFile()&&e.name==='source.json')out.push(p);}return out;}function readSet(file){return new Set(fs.readFileSync(file,'utf8').split(/\r?\n/).map(x=>x.trim()).filter(Boolean));}function inRanges(seed,ranges){for(const s of ranges){const[a,b]=s.split('..').map(Number);if(seed>=a&&seed<=b)return true;}return false;}
function collectG3(result,sets){const p=result.sourceSelection?.production?.pairs,i=result.sourceSelection?.independent?.pairs;need(Array.isArray(p)&&Array.isArray(i),'G3 pairs missing');const project=rows=>rows.map(row=>({sourceSeed:row.sourceSeed,namua:row.namua&&{sourceSeed:row.namua.sourceSeed,rootRawSha256:row.namua.rootRawSha256,sourceTrajectorySha256:row.namua.sourceTrajectorySha256,openingPrefixSha256:row.namua.openingPrefixSha256},mtaji:row.mtaji&&{sourceSeed:row.mtaji.sourceSeed,rootRawSha256:row.mtaji.rootRawSha256,sourceTrajectorySha256:row.mtaji.sourceTrajectorySha256,openingPrefixSha256:row.mtaji.openingPrefixSha256}}));need(stable(project(p))===stable(project(i)),'G3 identity mismatch');for(const row of p){sets.seed.add(row.sourceSeed);for(const r of[row.namua,row.mtaji])if(r){sets.seed.add(r.sourceSeed);sets.root.add(r.rootRawSha256);sets.trajectory.add(r.sourceTrajectorySha256);if(r.openingPrefixSha256)sets.prefix.add(r.openingPrefixSha256);}}}
function loadLegacy(){const cfg=SPEC.identityFirewalls.g4_01Legacy,fw=readBound(cfg.path,cfg.gitBlobSha),base=path.dirname(path.join(ROOT,cfg.path)),trajectory=new Set(),root=new Set();for(const f of fw.stage1rSfcdf.files){const vals=fs.readFileSync(path.join(base,f.path),'utf8').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(f.path.includes('source-trajectory'))for(const v of vals)trajectory.add(v);else if(f.path.includes('root-raw'))for(const v of vals)root.add(v);}need(trajectory.size===fw.stage1rSfcdf.sourceTrajectorySha256Count,'legacy trajectory count mismatch');need(root.size===fw.stage1rSfcdf.completeAnchorRootRawSha256Count,'legacy root count mismatch');return{trajectory,root};}
function loadStudy1(){const cfg=SPEC.identityFirewalls.study1,fw=readBound(cfg.path,cfg.gitBlobSha),base=path.dirname(path.join(ROOT,cfg.path));need(fw.identityCoreSha256===cfg.identityCoreSha256,'Study1 firewall core mismatch');return{trajectory:readSet(path.join(base,'sourceTrajectorySha256.txt')),prefix:readSet(path.join(base,'openingPrefixSha256.txt')),root:readSet(path.join(base,'rootRawSha256.txt'))};}
function loadStudy2(){const cfg=SPEC.identityFirewalls.study2,fw=readBound(cfg.path,cfg.gitBlobSha),base=path.dirname(path.join(ROOT,cfg.path));need(fw.identityCoreSha256===cfg.identityCoreSha256,'Study2 firewall core mismatch');need(fw.scientificSeedReplay===false&&fw.scientificEndpointLoaded===false,'Study2 firewall boundary mismatch');const out={trajectory:readSet(path.join(base,'SOURCE_TRAJECTORY_SHA256.txt')),prefix:readSet(path.join(base,'OPENING_PREFIX_SHA256.txt')),root:readSet(path.join(base,'RAW_ROOT_SHA256.txt'))};need(out.trajectory.size===fw.identityCounts.uniqueSourceTrajectorySha256&&out.prefix.size===fw.identityCounts.uniqueOpeningPrefixSha256&&out.root.size===fw.identityCounts.uniqueRawRootSha256,'Study2 firewall count mismatch');return out;}
function limits(){const x=SPEC.resourceCeilings.perSelectedRoot;return{distinctRawStates:x.maxDistinctRawStates,uniqueTransitions:x.maxUniqueTransitions,parentExpansions:x.maxParentExpansions,legalMoveEvaluations:x.maxLegalMoveEvaluations,treeNodeOccurrences:x.maxTreeNodeOccurrences};}function preflight(root,seed){const pp=P.preflight(E,root.state,seed,root.ply,limits()),ii=I.preflight(E,root.state,seed,root.ply,limits());need(P.canonical(pp)===I.canonical(ii),`preflight mismatch seed=${seed} ply=${root.ply}`);return pp;}
function main(){const a=parse(),input=path.resolve(a.input||''),output=path.resolve(a.output||'');need(input&&output&&fs.existsSync(input),'--input/--output required');const g3={seed:new Set(),trajectory:new Set(),prefix:new Set(),root:new Set()};collectG3(readBound(SPEC.identityFirewalls.g3_04Stage1.path,SPEC.identityFirewalls.g3_04Stage1.gitBlobSha),g3);collectG3(readBound(SPEC.identityFirewalls.g3_04Stage2.path,SPEC.identityFirewalls.g3_04Stage2.gitBlobSha),g3);const legacy=loadLegacy(),study1=loadStudy1(),study2=loadStudy2();const files=walk(input);need(files.length===SPEC.freshSeedSlots.primary.count,`expected ${SPEC.freshSeedSlots.primary.count} sources, got ${files.length}`);const seen=new Set(),sourceRows=[],candidates=[],rejects=[];fs.mkdirSync(output,{recursive:true});
 for(const file of files){const buf=fs.readFileSync(file),j=JSON.parse(buf.toString('utf8'));need(j.studyId==='SFCDFT-STUDY3'&&j.stageId===SPEC.stageId,'source identity mismatch');need(!seen.has(j.slotSeed),`duplicate slot ${j.slotSeed}`);seen.add(j.slotSeed);const primary=SPEC.freshSeedSlots.primary;need(j.slotSeed>=primary.seedStart&&j.slotSeed<=primary.seedEnd,`slot out of range ${j.slotSeed}`);need(j.effectiveSeed===j.slotSeed||j.effectiveSeed===j.slotSeed+1000000,'effective seed invalid');need(j.seedRole===(j.effectiveSeed===j.slotSeed?'PRIMARY':'PAIRED-RESERVE'),'seed role mismatch');for(const fw of[SPEC.identityFirewalls.g4_01Legacy,SPEC.identityFirewalls.study1,SPEC.identityFirewalls.study2])need(!inRanges(j.slotSeed,fw.forbiddenSeedNamespaces)&&!inRanges(j.effectiveSeed,fw.forbiddenSeedNamespaces),`forbidden seed collision ${j.slotSeed}`);need(j.endpointValuesRetained===false,'source retained endpoints');need(SPEC.sourceAcquisition.normalSourceStatuses.includes(j.candidateStatus),'invalid source status');need(j.postCandidateContinuationCount===0,'post-candidate continuation nonzero');
  const dest=path.join(output,'source',String(j.slotSeed),'source.json');fs.mkdirSync(path.dirname(dest),{recursive:true});fs.writeFileSync(dest,buf);sourceRows.push({slotSeed:j.slotSeed,effectiveSeed:j.effectiveSeed,seedRole:j.seedRole,domainId:j.domainId,candidateStatus:j.candidateStatus,sha256:sha(buf)});
  let reason=null;if(j.candidateStatus!=='CANDIDATE-PAIR-COMPLETE'||!j.pairComplete||!j.namua||!j.mtaji)reason=j.candidateStatus;if(!reason)need(j.openingPrefixAvailable===true&&j.openingPrefixLength===16&&typeof j.openingPrefixSha256==='string','candidate opening prefix invalid');
  if(!reason&&(g3.seed.has(j.slotSeed)||g3.seed.has(j.effectiveSeed)))reason='G3-SEED-COLLISION';if(!reason&&g3.trajectory.has(j.sourceTrajectorySha256))reason='G3-TRAJECTORY-COLLISION';if(!reason&&g3.prefix.has(j.openingPrefixSha256))reason='G3-OPENING-PREFIX-COLLISION';if(!reason&&(g3.root.has(j.namua.rawStateSha256)||g3.root.has(j.mtaji.rawStateSha256)))reason='G3-RAW-ROOT-COLLISION';
  if(!reason&&legacy.trajectory.has(j.sourceTrajectorySha256))reason='G4-01-TRAJECTORY-COLLISION';if(!reason&&(legacy.root.has(j.namua.rawStateSha256)||legacy.root.has(j.mtaji.rawStateSha256)))reason='G4-01-RAW-ROOT-COLLISION';
  if(!reason&&study1.trajectory.has(j.sourceTrajectorySha256))reason='STUDY1-TRAJECTORY-COLLISION';if(!reason&&study1.prefix.has(j.openingPrefixSha256))reason='STUDY1-OPENING-PREFIX-COLLISION';if(!reason&&(study1.root.has(j.namua.rawStateSha256)||study1.root.has(j.mtaji.rawStateSha256)))reason='STUDY1-RAW-ROOT-COLLISION';
  if(!reason&&study2.trajectory.has(j.sourceTrajectorySha256))reason='STUDY2-TRAJECTORY-COLLISION';if(!reason&&study2.prefix.has(j.openingPrefixSha256))reason='STUDY2-OPENING-PREFIX-COLLISION';if(!reason&&(study2.root.has(j.namua.rawStateSha256)||study2.root.has(j.mtaji.rawStateSha256)))reason='STUDY2-RAW-ROOT-COLLISION';
  if(reason){rejects.push({slotSeed:j.slotSeed,domainId:j.domainId,reason});continue;}const key=sha(Buffer.from(`${SPEC.stageId}|${j.domainId}|${j.slotSeed}|${j.effectiveSeed}|${j.sourceTrajectorySha256}|${j.openingPrefixSha256}|${j.namua.rawStateSha256}|${j.mtaji.rawStateSha256}`,'utf8'));candidates.push({slotSeed:j.slotSeed,effectiveSeed:j.effectiveSeed,seedRole:j.seedRole,domainId:j.domainId,selectionKey:key,source:j});
 }
 need(seen.size===SPEC.freshSeedSlots.primary.count,'source coverage mismatch');sourceRows.sort((a,b)=>a.slotSeed-b.slotSeed);const reserveCount=sourceRows.filter(x=>x.seedRole==='PAIRED-RESERVE').length;need(reserveCount<=SPEC.freshSeedSlots.maxInfrastructureReplacements,'reserve count exceeds maximum');const selected=[],domainSupport={};for(const d of SPEC.domains){const xs=candidates.filter(x=>x.domainId===d.domainId).sort((a,b)=>a.selectionKey.localeCompare(b.selectionKey));let tried=0,preflightRejected=0,chosen=0;for(const x of xs){if(chosen>=d.targetPairs)break;tried++;const pn=preflight(x.source.namua,x.effectiveSeed),pm=preflight(x.source.mtaji,x.effectiveSeed);if(!pn.eligible||!pm.eligible){preflightRejected++;rejects.push({slotSeed:x.slotSeed,domainId:x.domainId,reason:`PREFLIGHT-INELIGIBLE:${pn.reasonCode||'NA'}:${pm.reasonCode||'NA'}`});continue;}chosen++;const rank=chosen,rel=`selected/${d.domainId}/${String(rank).padStart(2,'0')}-${x.slotSeed}.json`,out=path.join(output,rel);fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify(x.source)+'\n');selected.push({domainId:d.domainId,rank,slotSeed:x.slotSeed,effectiveSeed:x.effectiveSeed,seedRole:x.seedRole,selectionKey:x.selectionKey,sourceTrajectorySha256:x.source.sourceTrajectorySha256,openingPrefixSha256:x.source.openingPrefixSha256,namuaRawSha256:x.source.namua.rawStateSha256,mtajiRawSha256:x.source.mtaji.rawStateSha256,preflightDigest:sha(Buffer.from(stable({namua:pn,mtaji:pm}),'utf8')),path:rel});}domainSupport[d.domainId]={identityEligible:xs.length,preflightTried:tried,preflightRejected,target:d.targetPairs,selected:chosen};}
 selected.sort((a,b)=>a.domainId.localeCompare(b.domainId)||a.rank-b.rank);const selectionReady=SPEC.domains.every(d=>domainSupport[d.domainId].selected===d.targetPairs),statusCounts={};for(const s of sourceRows)statusCounts[s.candidateStatus]=(statusCounts[s.candidateStatus]||0)+1;const rejectionCounts=Object.fromEntries([...new Set(rejects.map(x=>x.reason))].sort().map(r=>[r,rejects.filter(x=>x.reason===r).length]));const manifestCore={studyId:'SFCDFT-STUDY3',stageId:SPEC.stageId,sourceArtifactCount:sourceRows.length,primaryCount:sourceRows.filter(x=>x.seedRole==='PRIMARY').length,reserveCount,noCandidateCount:sourceRows.filter(x=>x.candidateStatus!=='CANDIDATE-PAIR-COMPLETE').length,engineGuardCensoringCount:sourceRows.filter(x=>x.candidateStatus==='NO-CANDIDATE-ENGINE-GUARD-CENSORING').length,sourceStatusCounts:statusCounts,sourceEntries:sourceRows,identityFirewallCounts:{g3Seed:g3.seed.size,g3Trajectory:g3.trajectory.size,g3OpeningPrefix:g3.prefix.size,g3Root:g3.root.size,g4LegacyTrajectory:legacy.trajectory.size,g4LegacyRoot:legacy.root.size,study1Trajectory:study1.trajectory.size,study1OpeningPrefix:study1.prefix.size,study1Root:study1.root.size,study2Trajectory:study2.trajectory.size,study2OpeningPrefix:study2.prefix.size,study2Root:study2.root.size},rejectionCounts};const sourceManifest={schemaVersion:1,...manifestCore,deterministicCoreSha256:sha(Buffer.from(stable(manifestCore),'utf8'))};fs.writeFileSync(path.join(output,'SOURCE_MANIFEST.json'),JSON.stringify(sourceManifest,null,2)+'\n');const selectedCore={studyId:'SFCDFT-STUDY3',stageId:SPEC.stageId,selectionReady,decision:selectionReady?'READY-FOR-SEED-FREE-MEASUREMENT':'NON-ESTIMABLE',domainSupport,selectedPairCount:selected.length,selectedPairs:selected};const selectedManifest={schemaVersion:1,...selectedCore,deterministicCoreSha256:sha(Buffer.from(stable(selectedCore),'utf8'))};fs.writeFileSync(path.join(output,'SELECTED_SOURCE_MANIFEST.json'),JSON.stringify(selectedManifest,null,2)+'\n');fs.writeFileSync(path.join(output,'REJECTIONS.json'),JSON.stringify({schemaVersion:1,studyId:'SFCDFT-STUDY3',stageId:SPEC.stageId,rejections:rejects},null,2)+'\n');process.stdout.write(JSON.stringify({event:'SOURCE-BUNDLE-COMMIT',sourceCount:sourceRows.length,reserveCount,selectionReady,selectedPairCount:selected.length,rejectionCounts,sourceManifestCore:sourceManifest.deterministicCoreSha256,selectedManifestCore:selectedManifest.deterministicCoreSha256})+'\n');}
main();
